382	    const name = normalizeWorkspaceName(basename(path)) ?? DEFAULT_WORKSPACE_NAME;
383	    const minted: WorkspaceIdentity = {
384	      version: 1,
385	      id: this.env.newId(),
386	      name,
387	      color: nextWorkspaceColor(this.key.entries.map((e) => e.color)),
388	      initials: deriveInitials(name),
389	      createdAt: now,
390	    };
391	    const entry = entryFromIdentity(minted, path, now);
392	    try {
393	      await writeIdentity(path, minted);
394	    } catch {
395	      entry.pendingInit = true;
396	    }
397	    this.key.entries.push(entry);
398	    return entry;
399	  }
