401	  get state(): Readonly<WorkspacesKey> {
402	    return this.key;
403	  }
404	
405	  entries(): readonly WorkspaceEntry[] {
406	    return this.key.entries;
407	  }
408	
409	  get(id: string): WorkspaceEntry | undefined {
410	    return this.key.entries.find((e) => e.id === id);
411	  }
412	
413	  active(): WorkspaceEntry {
414	    return this.get(this.key.activeId) ?? this.key.entries[0]!;
415	  }
416	
417	  isDefaultPath(path: string): boolean {
418	    return samePath(path, this.env.defaultDirectory);
419	  }
420	
421	  /**
422	   * The one-time upgrade (part 1b): a "Default workspace" that part 1 migrated as rose takes
423	   * Kaipu's brand color. The marker is stored first, in the same write, so it runs once; the
424	   * folder's identity.json follows through `pendingColorUpgrade`, which also covers a folder
425	   * that is not connected right now: when it is back, the file is written only if it still
426	   * holds the old Default and rose. A name or color the user already changed, here or on
427	   * another Mac, is left as it is.
428	   */
429	  private async upgradeDefaultColor(): Promise<void> {
430	    const owner = this.get(this.key.legacyCloudOwnerId);
431	    let upgrade = owner?.name === DEFAULT_WORKSPACE_NAME && owner.color === "rose";
432	    if (owner && upgrade) {
433	      const file = await readIdentity(owner.path);
434	      // The folder's own file wins (renamed or recolored on another Mac): leave it as it is,
435	      // and a probe will refresh this Mac's cache from it.
436	      if (
437	        file.kind === "ok" &&
438	        (file.identity.color !== "rose" || file.identity.name !== DEFAULT_WORKSPACE_NAME)
439	      ) {
440	        upgrade = false;
441	      }
442	      if (file.kind === "unreadable") upgrade = false;
443	    }
444	    try {
445	      await this.update((key) => {
446	        key.kaipuColorApplied = true;
447	        if (owner && upgrade) {
448	          owner.color = DEFAULT_WORKSPACE_COLOR;
449	          owner.pendingColorUpgrade = true;
450	        }
451	      });
452	    } catch (error) {
453	      // preferences.json could not be written: retried on the next launch.
454	      console.error("workspaces: could not store the color upgrade", error);
455	      return;
456	    }
457	    if (owner && upgrade) await this.availability(owner.id);
458	  }
459	
460	  /** The folder next to the Default workspace's, or the nearest reachable fallback. */
461	  private async newWorkspaceParent(): Promise<string | null> {
462	    const defaultEntry =
463	      this.get(this.key.legacyCloudOwnerId) ??
464	      this.key.entries.find((e) => this.isDefaultPath(e.path));
465	    for (const candidate of [defaultEntry?.path, this.env.defaultDirectory, this.active().path]) {
466	      if (!candidate) continue;
467	      const parent = dirname(candidate);
468	      if (await isDirectory(parent)) return parent;
469	    }
470	    return null;
471	  }
472	
473	  /**
474	   * Where "New workspace" would put `name`'s folder, and whether it can be used: `Kaipu Record
475	   * — <name>` next to the Default workspace's folder. Read-only; creates nothing.
476	   */
477	  async checkNewLocation(name: string): Promise<LocationCheck> {
478	    const normalized = validateWorkspaceName(name, []);
479	    if (!normalized.ok) return { path: null, state: "parent-missing" };
480	    const parent = await this.newWorkspaceParent();
481	    if (!parent) return { path: null, state: "parent-missing" };
482	    const path = join(parent, newWorkspaceFolderName(normalized.name));
483	    try {
484	      if (!(await stat(path)).isDirectory()) return { path, state: "not-empty" };
485	      const content = (await readdir(path)).filter((n) => !IGNORED_FOLDER_ENTRIES.has(n));
486	      return { path, state: content.length === 0 ? "empty" : "not-empty" };
487	    } catch (error) {
488	      // Nothing there is the good case; anything else (no permission) cannot be used.
489	      return (error as NodeJS.ErrnoException).code === "ENOENT"
490	        ? { path, state: "free" }
491	        : { path, state: "not-empty" };
492	    }
493	  }
494	
495	  /**
496	   * Create a workspace in a NEW folder (the owner's request, part 1b): `Kaipu Record — <name>`
497	   * next to the Default workspace's. Writes only Kaipu's own files; a folder that is there and
498	   * not empty is refused untouched. Does not switch.
499	   */
500	  async create(input: { name: string; color: string }): Promise<CreateOutcome> {
501	    if (this.readOnly) return { ok: false, reason: "read-only" };
502	    const checked = validateWorkspaceName(input.name, this.key.entries);
503	    if (!checked.ok) {
504	      return { ok: false, reason: checked.reason === "taken" ? "name-taken" : "invalid-name" };
505	    }
506	    if (!isTagColor(input.color)) return { ok: false, reason: "invalid-color" };
507	    const location = await this.checkNewLocation(checked.name);
508	    if (!location.path) return { ok: false, reason: "parent-missing" };
509	    if (location.state === "not-empty") return { ok: false, reason: "exists" };
510	
511	    const path = location.path;
512	    let madeFolder = false;
513	    if (location.state === "free") {
514	      try {
515	        // One level, never recursive: a missing parent stays missing.
516	        await mkdir(path);
517	        madeFolder = true;
518	      } catch (error) {
519	        const code = (error as NodeJS.ErrnoException).code;
520	        return { ok: false, reason: code === "EEXIST" ? "exists" : "not-writable" };
521	      }
522	    }
523	    const undo = async (): Promise<void> => {
524	      await removeIdentity(path);
525	      if (madeFolder) await rmdir(path).catch(() => {});
526	    };
527	    const identity: WorkspaceIdentity = {
528	      version: 1,
529	      id: this.env.newId(),
530	      name: checked.name,
531	      color: input.color,
532	      initials: deriveInitials(checked.name),
533	      createdAt: WorkspaceRegistry.now(this.env),
534	    };
535	    try {
536	      await writeIdentity(path, identity);
537	    } catch {
538	      await undo();
539	      return { ok: false, reason: "not-writable" };
540	    }
541	    const entry = entryFromIdentity(identity, path, identity.createdAt);
542	    try {
543	      await this.update((key) => {
544	        // Re-checked inside the write: two creates cannot both take one name.
545	        if (validateWorkspaceName(checked.name, key.entries).ok === false)
546	          throw new NameTakenError();
547	        key.entries.push(entry);
548	      });
549	    } catch (error) {
550	      await undo();
551	      return { ok: false, reason: error instanceof NameTakenError ? "name-taken" : "not-writable" };
552	    }
553	    return { ok: true, entry };
554	  }
555	
556	  /**
557	   * Rename and/or recolor. The folder's `identity.json` is the authority (it travels with the
558	   * folder), so it is written first, atomically; the registry's cache follows. A change the
559	   * folder cannot take is refused whole. A workspace that is not connected is changed in the
560	   * registry only and carries `pendingIdentity`, so the change reaches the folder when it is
561	   * back instead of the folder's older file undoing it. Initials that were derived from the
562	   * old name follow the new one; initials the user chose stay.
563	   */
564	  async edit(id: string, patch: { name?: string; color?: string }): Promise<EditOutcome> {
565	    if (this.readOnly) return { ok: false, reason: "read-only" };
566	    const before = this.get(id);
567	    if (!before) return { ok: false, reason: "unknown" };
568	    let name = before.name;
569	    if (patch.name !== undefined) {
570	      const checked = validateWorkspaceName(patch.name, this.key.entries, id);
571	      if (!checked.ok) {
572	        return { ok: false, reason: checked.reason === "taken" ? "name-taken" : "invalid-name" };
573	      }
574	      name = checked.name;
575	    }
576	    let color = before.color;
577	    if (patch.color !== undefined) {
578	      if (!isTagColor(patch.color)) return { ok: false, reason: "invalid-color" };
579	      color = patch.color;
580	    }
581	    if (name === before.name && color === before.color) {
582	      return {
583	        ok: true,
584	        entry: before,
585	        savedToFolder:
586	          !before.pendingIdentity && !before.pendingColorUpgrade && !before.pendingInit,
587	      };
588	    }
589	
590	    // A probe first: a pending entry may adopt its folder's id, and it says whether to write.
591	    const probe = await this.availability(id);
592	    const entry = this.get(probe.id);
593	    if (!entry) return { ok: false, reason: "unknown" };
594	    const derived = entry.initials === undefined || entry.initials === deriveInitials(entry.name);
595	    const initials = derived ? deriveInitials(name) : entry.initials;
596	    const previous = await readIdentity(entry.path);
597	
598	    let savedToFolder = false;
599	    if (probe.availability.state === "available") {
600	      const next: WorkspaceIdentity =
601	        previous.kind === "ok"
602	          ? { ...previous.identity, name, color, ...(initials ? { initials } : {}) }
603	          : {
604	              version: 1,
605	              id: entry.id,
606	              name,
607	              color,
608	              ...(initials ? { initials } : {}),
609	              createdAt: entry.addedAt,
610	            };
611	      try {
612	        await writeIdentity(entry.path, next);
613	      } catch {
614	        return { ok: false, reason: "not-writable" };
615	      }
616	      savedToFolder = true;
617	    }
618	    try {
619	      await this.update((key) => {
620	        // Re-checked inside the write, like create: two edits cannot both take one name.
621	        if (!validateWorkspaceName(name, key.entries, entry.id).ok) throw new NameTakenError();
622	        const target = key.entries.find((e) => e.id === entry.id);
623	        if (!target) return;
624	        target.name = name;
625	        target.color = color;
626	        if (initials) target.initials = initials;
627	        delete target.pendingInit;
628	        // An edit owns the folder's identity from here, so a deferred upgrade has nothing left to decide.
629	        delete target.pendingColorUpgrade;
630	        if (savedToFolder) delete target.pendingIdentity;
631	        else target.pendingIdentity = true;
632	      });
633	    } catch (error) {
